#!/usr/bin/env python3\n"""Phase 14A.0 — acquire PIT NIFTY-50 cash OHLCV from NSE daily bhavcopies.\n\nThe script downloads official per-day NSE cash-market bhavcopy files, applies a\nsecondary PIT NIFTY-50 membership reconstruction, reverses known ticker renames\nby effective date, and keeps only the NIFTY-50 members that were eligible on\neach trading day.\n\nIt is intentionally a discovery-input builder. It does not create adjusted\nprices, infer missing data, or project today's constituent list backwards.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport time\nfrom datetime import date, datetime, timedelta\nfrom pathlib import Path\n\nimport pandas as pd\nimport requests\n\nURL = "https://nsearchives.nseindia.com/products/content/sec_bhavdata_full_{ddmmyyyy}.csv"\nKEEP_SERIES = {"EQ", "SM", "BE", "BZ", "ST"}\n\n\ndef load_membership(path: str) -> pd.DataFrame:\n    m = pd.read_csv(path, parse_dates=["valid_from", "valid_to"])\n    m = m[m["index_name"].eq("Nifty 50")].copy()\n    required = {"symbol", "valid_from", "valid_to"}\n    missing = sorted(required - set(m.columns))\n    if missing:\n        raise ValueError(f"membership missing columns: {missing}")\n    return m\n\n\ndef load_renames(path: str) -> list[dict]:\n    obj = json.loads(Path(path).read_text(encoding="utf-8"))\n    return list(obj.get("renames", []))\n\n\ndef actual_symbol(canonical: str, trade_date: pd.Timestamp, renames: list[dict]) -> str:\n    """Reverse canonical rename chains for dates before each rename became effective."""\n    current = canonical\n    # Reverse in latest-effective-date-first order so chained renames resolve cleanly.\n    rules = sorted(\n        [r for r in renames if r.get("old") and r.get("new") and r.get("old") != r.get("new")],\n        key=lambda r: r.get("effective_date") or "1900-01-01",\n        reverse=True,\n    )\n    changed = True\n    while changed:\n        changed = False\n        for rule in rules:\n            effective = rule.get("effective_date")\n            if not effective or str(effective).endswith("XX"):\n                continue\n            effective_ts = pd.Timestamp(effective)\n            if trade_date < effective_ts and current == rule["new"]:\n                current = rule["old"]\n                changed = True\n    return current\n\n\ndef members_on(membership: pd.DataFrame, trade_date: pd.Timestamp, renames: list[dict]) -> dict[str, str]:\n    active = membership[\n        (membership["valid_from"] <= trade_date)\n        & (membership["valid_to"].isna() | (trade_date < membership["valid_to"]))\n    ]\n    out = {}\n    for canonical in sorted(active["symbol"].dropna().astype(str).unique()):\n        out[actual_symbol(canonical, trade_date, renames)] = canonical\n    return out\n\n\ndef parse_bhavcopy(content: bytes, trade_date: pd.Timestamp, member_map: dict[str, str]) -> pd.DataFrame:\n    from io import BytesIO\n    raw = pd.read_csv(BytesIO(content))\n    raw.columns = [str(c).strip() for c in raw.columns]\n    required = {"SYMBOL", "SERIES", "DATE1", "OPEN_PRICE", "HIGH_PRICE", "LOW_PRICE", "CLOSE_PRICE", "PREV_CLOSE", "TTL_TRD_QNTY", "TURNOVER_LACS"}\n    missing = sorted(required - set(raw.columns))\n    if missing:\n        raise ValueError(f"bhavcopy missing columns: {missing}")\n    raw["SYMBOL"] = raw["SYMBOL"].astype(str).str.strip()\n    raw["SERIES"] = raw["SERIES"].astype(str).str.strip()\n    raw = raw[raw["SERIES"].isin(KEEP_SERIES)]\n    raw = raw[raw["SYMBOL"].isin(member_map.keys())].copy()\n    if raw.empty:\n        return pd.DataFrame(columns=["date", "symbol", "symbol_raw", "series", "open", "high", "low", "close", "prev_close", "volume_shares", "turnover_inr"])\n    raw["date"] = trade_date.date().isoformat()\n    raw["symbol_raw"] = raw["SYMBOL"]\n    raw["symbol"] = raw["SYMBOL"].map(member_map)\n    for source, target in (("OPEN_PRICE", "open"), ("HIGH_PRICE", "high"), ("LOW_PRICE", "low"), ("CLOSE_PRICE", "close"), ("PREV_CLOSE", "prev_close"), ("TTL_TRD_QNTY", "volume_shares"), ("TURNOVER_LACS", "turnover_inr")):\n        raw[target] = pd.to_numeric(raw[source], errors="coerce")\n    raw["turnover_inr"] = raw["turnover_inr"] * 1e5\n    out = raw[["date", "symbol", "symbol_raw", "SERIES", "open", "high", "low", "close", "prev_close", "volume_shares", "turnover_inr"]].rename(columns={"SERIES":"series"})\n    return out\n\n\ndef date_range(start: date, end: date):\n    cur = start\n    one = timedelta(days=1)\n    while cur <= end:\n        if cur.weekday() < 5:\n            yield cur\n        cur += one\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--membership", required=True)\n    ap.add_argument("--renames", required=True)\n    ap.add_argument("--start", default="2020-04-13")\n    ap.add_argument("--end", default="2026-05-14")\n    ap.add_argument("--output", required=True)\n    ap.add_argument("--sleep", type=float, default=0.25)\n    args = ap.parse_args()\n\n    start = pd.Timestamp(args.start).date()\n    end = pd.Timestamp(args.end).date()\n    membership = load_membership(args.membership)\n    renames = load_renames(args.renames)\n    session = requests.Session()\n    session.headers.update({"User-Agent": "Mozilla/5.0", "Referer": "https://www.nseindia.com/"})\n\n    rows = []\n    failures = []\n    hits = 0\n    for d in date_range(start, end):\n        trade_date = pd.Timestamp(d)\n        member_map = members_on(membership, trade_date, renames)\n        if not member_map:\n            continue\n        url = URL.format(ddmmyyyy=d.strftime("%d%m%Y"))\n        try:\n            resp = session.get(url, timeout=30)\n        except requests.RequestException as exc:\n            failures.append({"date": d.isoformat(), "status": "request_error", "error": str(exc)[:120]})\n            continue\n        if resp.status_code == 404:\n            continue\n        if resp.status_code != 200 or len(resp.content) < 5000:\n            failures.append({"date": d.isoformat(), "status": int(resp.status_code), "size": len(resp.content)})\n            continue\n        try:\n            parsed = parse_bhavcopy(resp.content, trade_date, member_map)\n        except Exception as exc:\n            failures.append({"date": d.isoformat(), "status": "parse_error", "error": str(exc)[:120]})\n            continue\n        rows.append(parsed)\n        hits += 1\n        if args.sleep > 0:\n            time.sleep(args.sleep)\n        if hits % 50 == 0:\n            print(f"processed {hits} trading files through {d}", flush=True)\n\n    if not rows:\n        raise SystemExit("no NIFTY-50 rows acquired")\n    df = pd.concat(rows, ignore_index=True)\n    df = df.sort_values(["date", "symbol"]).reset_index(drop=True)\n    out = Path(args.output)\n    out.parent.mkdir(parents=True, exist_ok=True)\n    df.to_csv(out, index=False)\n    manifest = out.with_suffix(".manifest.json")\n    manifest.write_text(json.dumps({\n        "source_url_template": URL,\n        "start": args.start,\n        "end": args.end,\n        "trading_files_with_rows": int(hits),\n        "rows": int(len(df)),\n        "unique_symbols": int(df["symbol"].nunique()),\n        "min_date": str(df["date"].min()),\n        "max_date": str(df["date"].max()),\n        "failures": failures[:200],\n        "n_failures": len(failures),\n        "membership_source": str(args.membership),\n        "rename_source": str(args.renames),\n    }, indent=2) + "\n", encoding="utf-8")\n    print(f"wrote {out} with {len(df):,} rows; failures={len(failures)}")\n\n\nif __name__ == "__main__":\n    main()